catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}

    var today = new Date();
    var selectedDate = new Date(newValue);
	selectedDate.setHours(0, 0, 0, 0);
  	today.setHours(0, 0, 0, 0);
	var departingOn = new Date(g_form.getValue('departing_on'));
	departingOn.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
       //alert('You cannot select past date');
	   g_form.setValue('returning_on', '');
	   g_form.showFieldMsg('returning_on', 'Please enter a date in the future.', 'error');
	   //g_form.clearValue('returning_on');
	   return;
    }

	if (selectedDate < departingOn) {
	   g_form.setValue('returning_on', '');
	   g_form.showFieldMsg('returning_on', 'Please enter a date that falls after the departure date.', 'error');
	   return;
	}

}
